import AgoraRTC from 'agora-rtc-sdk-ng'

import { useGameStore } from '../../stores/gameStore'
import { useVoiceStore } from '../../stores/voiceStore'
import { useEffect, useRef, useState } from 'react'

// Create a single global client instance for Agora
// We use the RTC mode and vp8 codec which is standard for high quality audio/video
const client = AgoraRTC.createClient({ mode: 'rtc', codec: 'vp8' })

// Map to track timeouts for the speaking indicator debounce
const speakingTimeouts: Record<string, ReturnType<typeof setTimeout>> = {}

const getNumericUid = (id: string) => {
  let hash = 0;
  for (let i = 0; i < id.length; i++) {
    hash = Math.imul(31, hash) + id.charCodeAt(i) | 0;
  }
  // Ensure the ID is exactly between 1 and 65535
  return (Math.abs(hash) % 65534) + 1;
}

export default function AgoraVoiceManager() {
  const roomCode = useGameStore(s => s.room?.code)
  const myPlayerId = useGameStore(s => s.myPlayerId)
  const players = useGameStore(s => s.players)
  const { isMuted, isDeafened, setSpeaking, resetVoice } = useVoiceStore()

  const [localTrack, setLocalTrack] = useState<any | null>(null)
  const [remoteUsers, setRemoteUsers] = useState<any[]>([])

  const playersRef = useRef(players)
  const isMutedRef = useRef(isMuted)
  const isDeafenedRef = useRef(isDeafened)
  const myPlayerIdRef = useRef(myPlayerId)

  // Sync refs to avoid stale closures in listeners
  useEffect(() => { playersRef.current = players }, [players])
  useEffect(() => { isMutedRef.current = isMuted }, [isMuted])
  useEffect(() => { isDeafenedRef.current = isDeafened }, [isDeafened])
  useEffect(() => { myPlayerIdRef.current = myPlayerId }, [myPlayerId])

  // Reset voice store on mount and cleanup on unmount
  useEffect(() => {
    resetVoice()
    return () => resetVoice()
  }, [resetVoice])

  // Manage joining the room and publishing our mic track
  useEffect(() => {
    const appId = import.meta.env.VITE_AGORA_APP_ID
    if (!appId || !roomCode || !myPlayerId) {
      return
    }

    let active = true
    let micTrack: any | null = null
    const numericUid = getNumericUid(myPlayerId)

    const setupVoice = async () => {
      try {
        console.log("[Agora] Joining channel:", roomCode, "with UID:", numericUid)
        await client.join(appId, roomCode, null, numericUid)

        if (!active) {
          await client.leave()
          return
        }

        console.log("[Agora] Creating microphone track...")
        micTrack = await AgoraRTC.createMicrophoneAudioTrack({
          ANS: true,
          AEC: true
        })

        if (!active) {
          micTrack.close()
          await client.leave()
          return
        }

        setLocalTrack(micTrack)
        // Set initial mute state
        await micTrack.setMuted(isMutedRef.current)

        console.log("[Agora] Publishing microphone track...")
        await client.publish(micTrack)
        console.log("[Agora] Successfully joined channel and published track.")
      } catch (err: any) {
        const isAborted = err?.code === 'OPERATION_ABORTED' || err?.message?.includes('OPERATION_ABORTED')
        if (isAborted) {
          console.log("[Agora] Join/Publish aborted (likely due to room change or StrictMode cleanup).")
        } else {
          console.error("[Agora] Error during channel join or publish:", err)
        }
      }
    }

    setupVoice()

    return () => {
      active = false
      setLocalTrack(null)
      const cleanup = async () => {
        if (micTrack) {
          console.log("[Agora] Unpublishing and closing local track...")
          try {
            await client.unpublish(micTrack)
          } catch (e) {}
          micTrack.close()
        }
        try {
          console.log("[Agora] Leaving channel...")
          await client.leave()
        } catch (e) {}
      }
      cleanup()
    }
  }, [roomCode, myPlayerId])

  // Handle local mute state changes
  useEffect(() => {
    if (localTrack) {
      localTrack.setMuted(isMuted)
      if (isMuted && myPlayerId) {
        if (speakingTimeouts[myPlayerId]) {
          clearTimeout(speakingTimeouts[myPlayerId])
          delete speakingTimeouts[myPlayerId]
        }
        setSpeaking(myPlayerId, false)
      }
    }
  }, [isMuted, localTrack, myPlayerId, setSpeaking])

  // Track remote users and subscribe/play their audio tracks
  useEffect(() => {
    const handleUserPublished = async (user: any, mediaType: 'audio' | 'video') => {
      if (mediaType === 'audio') {
        console.log("[Agora] Remote user published audio:", user.uid)
        try {
          await client.subscribe(user, 'audio')
          setRemoteUsers(prev => {
            if (prev.find(u => u.uid === user.uid)) return prev
            return [...prev, user]
          })
          // Only play audio if we are not deafened
          if (!isDeafenedRef.current && user.audioTrack) {
            user.audioTrack.play()
          }
        } catch (err) {
          console.error("[Agora] Subscribe remote user audio error:", err)
        }
      }
    }

    const handleUserUnpublished = (user: any, mediaType: 'audio' | 'video') => {
      if (mediaType === 'audio') {
        console.log("[Agora] Remote user unpublished audio:", user.uid)
        if (user.audioTrack) {
          user.audioTrack.stop()
        }
        setRemoteUsers(prev => prev.filter(u => u.uid !== user.uid))
      }
    }

    const handleUserLeft = (user: any) => {
      console.log("[Agora] Remote user left:", user.uid)
      if (user.audioTrack) {
        user.audioTrack.stop()
      }
      setRemoteUsers(prev => prev.filter(u => u.uid !== user.uid))
    }

    client.on("user-published", handleUserPublished)
    client.on("user-unpublished", handleUserUnpublished)
    client.on("user-left", handleUserLeft)

    return () => {
      client.off("user-published", handleUserPublished)
      client.off("user-unpublished", handleUserUnpublished)
      client.off("user-left", handleUserLeft)
    }
  }, [])

  // Handle deafen toggle: stop or play remote audio tracks
  useEffect(() => {
    remoteUsers.forEach(user => {
      if (user.audioTrack) {
        if (isDeafened) {
          user.audioTrack.stop()
        } else {
          user.audioTrack.play()
        }
      }
    })
  }, [isDeafened, remoteUsers])

  // Set up volume indicators to power the glowing green rings around avatars!
  useEffect(() => {
    client.enableAudioVolumeIndicator()

    const handleVolumeIndicator = (volumes: { uid: string | number, level: number }[]) => {
      volumes.forEach((vol) => {
        // level goes from 0 to 100. >2 is a good sensitive threshold
        const speaking = vol.level > 2
        const numericUid = Number(vol.uid)

        let pId: string | undefined = undefined

        if (numericUid === 0 && myPlayerIdRef.current) {
          // Agora Web SDK sometimes reports local user as 0
          pId = myPlayerIdRef.current
        } else {
          // Reverse lookup: find which player ID matches this numeric UID
          const speakingPlayer = playersRef.current.find(p => getNumericUid(p.id) === numericUid)
          if (speakingPlayer) {
            pId = speakingPlayer.id
          }
        }

        if (pId) {
          if (speaking) {
            // Cancel any pending timeout that would remove the speaking ring
            if (speakingTimeouts[pId]) {
              clearTimeout(speakingTimeouts[pId])
              delete speakingTimeouts[pId]
            }

            // Show speaking (unless it's us and we are muted locally to prevent echo visuals)
            if (pId !== myPlayerIdRef.current || !isMutedRef.current) {
              setSpeaking(pId, true)
            }
          } else {
            // Debounce the stop-speaking indicator to prevent flickering
            if (!speakingTimeouts[pId]) {
              speakingTimeouts[pId] = setTimeout(() => {
                setSpeaking(pId, false)
                delete speakingTimeouts[pId]
              }, 300)
            }
          }
        }
      })
    }

    client.on("volume-indicator", handleVolumeIndicator)

    return () => {
      client.off("volume-indicator", handleVolumeIndicator)
    }
  }, [setSpeaking])

  return null
}

import { useState, useEffect } from 'react'
import { useGameStore } from '../../stores/gameStore'
import { supabase } from '../../lib/supabase'
import { playEmote, playClick } from '../../utils/sounds'
import { useLanguageStore } from '../../stores/languageStore'
import GameTableLayout from './GameTableLayout'
import PoliceSelection from './PoliceSelection'
import TutorialOverlay from './TutorialOverlay'

const EMOTES = ['🤨', '😇', '😡', '🤡', '🤫']

export default function DiscussionPhase() {
  const room = useGameStore((s) => s.room)
  const players = useGameStore((s) => s.players)
  const policeId = useGameStore((s) => s.policeId)
  const myPlayerId = useGameStore((s) => s.myPlayerId)
  const myRole = useGameStore((s) => s.myRole)
  const myRolePoints = useGameStore((s) => s.myRolePoints)
  const { t } = useLanguageStore()

  const [selectedId, setSelectedId] = useState<string | null>(null)

  const isPolice = myPlayerId === policeId
  const policePlayer = players.find((p) => p.id === policeId)

  if (!room) return null

  // The server only uses DISCUSSION for both discussing and accusing
  const isPolicePhase = room.phase === 'DISCUSSION' || room.phase === 'POLICE_SELECTION'

  const [timeLeft, setTimeLeft] = useState(() => {
    if (!room || !room.phaseEndsAt) return 60
    return Math.max(0, Math.floor((new Date(room.phaseEndsAt).getTime() - Date.now()) / 1000))
  })

  useEffect(() => {
    if (!room || room.phase !== 'DISCUSSION') return
    const interval = setInterval(() => {
      setTimeLeft(() => {
        if (!room.phaseEndsAt) return 0
        const diff = Math.floor((new Date(room.phaseEndsAt).getTime() - Date.now()) / 1000)
        if (diff <= 0) {
          clearInterval(interval)
          return 0
        }
        return diff
      })
    }, 500) // 500ms for more responsive updates
    return () => clearInterval(interval)
  }, [room?.phase, room?.phaseEndsAt])

  useEffect(() => {
    if (timeLeft <= 10 && timeLeft > 0) {
      playClick() // Ticking sound effect for urgency
    }
  }, [timeLeft])

  const handleEmote = (emoji: string) => {
    if (!room || !myPlayerId) return
    playEmote()
    const channel = supabase.channel(`room:${room.id}`)
    channel.send({
      type: 'broadcast',
      event: 'EMOTE',
      payload: { playerId: myPlayerId, emoji }
    })
    useGameStore.getState().setEmote(myPlayerId, emoji)
  }

  const handlePlayerTap = (id: string) => {
    if (id === myPlayerId) return

    playClick()

    if (isPolice && isPolicePhase) {
      setSelectedId(id)
    } else {
      if (!room || !myPlayerId) return
      const currentPointer = useGameStore.getState().pointers[myPlayerId]
      const toId = currentPointer === id ? null : id
      
      const channel = supabase.channel(`room:${room.id}`)
      channel.send({
        type: 'broadcast',
        event: 'POINTING',
        payload: { fromId: myPlayerId, toId }
      })
      useGameStore.getState().setPointer(myPlayerId, toId)
    }
  }

  // ── Top bar: Round info + Police announcement ──
  const topContent = (
    <div className="flex flex-col items-center gap-1.5">
      {/* Round badge */}
      <div className="px-4 py-1.5 rounded-full" style={{
        background: 'linear-gradient(180deg, rgba(13,7,4,0.9), rgba(26,15,8,0.85))',
        border: '1px solid rgba(90,66,41,0.4)',
        boxShadow: '0 4px 12px rgba(0,0,0,0.6)',
      }}>
        <span className="font-serif font-bold text-[11px] sm:text-xs uppercase tracking-[0.2em] text-[#c89f59]">
          {t.game.round} {room.currentRound} {t.game.of} {room.totalRounds}
        </span>
      </div>

      {/* Police announcement */}
      {policePlayer && (
        <div className="px-3 py-1 rounded-full flex items-center gap-2" style={{
          background: 'linear-gradient(180deg, rgba(30,58,138,0.7), rgba(15,23,42,0.8))',
          border: '1px solid rgba(59,130,246,0.3)',
          boxShadow: '0 0 15px rgba(59,130,246,0.15)',
        }}>
          <svg className="w-3 h-3 text-blue-400" viewBox="0 0 24 24" fill="currentColor">
            <path d="M12 1L3 5v6c0 5.55 3.84 10.74 9 12 5.16-1.26 9-6.45 9-12V5l-9-4z"/>
          </svg>
          <span className="text-blue-300 font-serif font-bold text-[10px] sm:text-xs tracking-wider">
            {policePlayer.username}
          </span>
          <span className="text-blue-400/60 text-[9px] sm:text-[10px] font-serif">{t.game.isThePolice}</span>
        </div>
      )}

      {/* Animated Timer Bar */}
      <div className={`w-full max-w-[180px] sm:max-w-[220px] mt-1 relative h-6 rounded-full overflow-hidden border shadow-lg ${timeLeft <= 10 ? 'border-red-500/60 animate-pulse' : 'border-[#c89f59]/40'}`} style={{
        background: 'linear-gradient(180deg, #1a0f08, #0a0604)',
        boxShadow: 'inset 0 2px 5px rgba(0,0,0,0.9)'
      }}>
        {/* Progress Fill */}
        <div 
          className="absolute top-0 bottom-0 left-0 transition-all duration-1000 ease-linear"
          style={{ 
            width: `${(timeLeft / 60) * 100}%`,
            background: timeLeft <= 10 
              ? 'linear-gradient(90deg, #7f1d1d, #ef4444)' 
              : 'linear-gradient(90deg, #7a5a18, #d4af37)',
            boxShadow: timeLeft <= 10 ? '0 0 15px rgba(239,68,68,0.8)' : '0 0 10px rgba(212,175,55,0.4)',
          }}
        />
        {/* Text Overlay */}
        <div className="absolute inset-0 flex items-center justify-center pointer-events-none">
          <span className={`font-serif font-black text-[10px] sm:text-[11px] tracking-[0.25em] uppercase z-10 drop-shadow-[0_2px_2px_rgba(0,0,0,0.8)] ${timeLeft <= 10 ? 'text-[#fee2e2]' : 'text-[#fff8e1]'}`}>
            {timeLeft === 0 ? t.game.timeUp : `0:${timeLeft.toString().padStart(2, '0')}`}
          </span>
        </div>
      </div>

      {/* Phase indicator */}
      {isPolicePhase && (
        <div className="px-3 py-1 rounded-full" style={{
          background: 'linear-gradient(180deg, rgba(120,53,15,0.7), rgba(80,20,10,0.8))',
          border: '1px solid rgba(251,146,60,0.3)',
        }}>
          <span className="text-orange-300 font-serif font-bold text-[9px] sm:text-[10px] tracking-wider uppercase animate-pulse">
            {isPolice ? t.game.selectThief : t.game.policeIsChoosing}
          </span>
        </div>
      )}
    </div>
  )

  // ── Center content: Discussion phase indicator ──
  const centerContent = (
    <div className="flex flex-col items-center gap-2 opacity-50">
      {/* Mask watermark */}
      <svg width="50" height="36" viewBox="0 0 40 28" fill="none" className="drop-shadow-lg">
        <path d="M20 2C14 2 10 8 10 12C10 16 14 20 16 20C18 20 18 18 20 16C22 18 22 20 24 20C26 20 30 16 30 12C30 8 26 2 20 2Z" fill="#c89f59" stroke="#5a3e15" strokeWidth="0.8"/>
        <circle cx="15" cy="11" r="2.5" fill="#0d0704" stroke="#5a3e15" strokeWidth="0.5"/>
        <circle cx="25" cy="11" r="2.5" fill="#0d0704" stroke="#5a3e15" strokeWidth="0.5"/>
        <path d="M17 16 Q20 19 23 16" stroke="#5a3e15" strokeWidth="0.8" fill="none"/>
      </svg>
      <span className="text-[#c89f59] font-serif text-[10px] tracking-widest uppercase">
        {isPolicePhase ? t.game.accusation : t.game.discussion}
      </span>
    </div>
  )

  // ── Bottom content: Role card + Police selection ──
  const bottomContent = (
    <div className="flex flex-col items-center gap-2 w-full">
      {/* Police selection (only for police during POLICE_SELECTION phase) */}
      {isPolice && isPolicePhase && (
        <div className="w-full">
          <PoliceSelection 
            selectedId={selectedId}
            onClearSelection={() => setSelectedId(null)}
            timeLeft={timeLeft}
          />
        </div>
      )}

      {/* Non-police waiting message during selection */}
      {!isPolice && isPolicePhase && (
        <div className="w-full rounded-lg py-3 text-center" style={{
          background: 'linear-gradient(180deg, rgba(13,7,4,0.9), rgba(26,15,8,0.85))',
          border: '1px solid rgba(90,66,41,0.3)',
          boxShadow: '0 4px 12px rgba(0,0,0,0.5)',
        }}>
          <span className="font-serif text-[#c89f59] text-xs sm:text-sm italic tracking-wide">
            {t.game.waitingForPolice}
          </span>
        </div>
      )}

      {/* Emote Bar */}
      <div className="flex justify-center gap-2 sm:gap-3 mb-2 w-full">
        {EMOTES.map(emoji => (
          <button
            key={emoji}
            onClick={() => handleEmote(emoji)}
            className="w-10 h-10 sm:w-11 sm:h-11 flex items-center justify-center rounded-full text-xl sm:text-2xl transition-transform active:scale-90 hover:scale-110"
            style={{
              background: 'linear-gradient(180deg, rgba(44,26,14,0.9), rgba(26,15,8,0.95))',
              border: '1px solid rgba(212,175,55,0.4)',
              boxShadow: '0 4px 12px rgba(0,0,0,0.6)',
            }}
          >
            {emoji}
          </button>
        ))}
      </div>

      {/* My role card */}
      {myRole && (
        <RoleCard role={myRole} points={myRolePoints} />
      )}
    </div>
  )

  return (
    <>
      <TutorialOverlay />
      <GameTableLayout
        players={players}
        myPlayerId={myPlayerId}
        policeId={policeId}
        selectedPlayerId={selectedId}
        onPlayerTap={handlePlayerTap}
        interactable={true}
        centerContent={centerContent}
        topContent={topContent}
        bottomContent={bottomContent}
      />
    </>
  )
}

/* ─── Role Card (bottom strip) ─── */
function RoleCard({ role, points }: { role: string; points: number | null }) {
  const { t } = useLanguageStore()
  const isPolice = role === 'Police'
  const isThief = role === 'Thief'

  const bgStyle = isPolice
    ? { background: 'linear-gradient(90deg, rgba(30,58,138,0.85), rgba(15,23,42,0.9))', border: '1px solid rgba(59,130,246,0.4)' }
    : isThief
    ? { background: 'linear-gradient(90deg, rgba(127,29,29,0.85), rgba(60,10,10,0.9))', border: '1px solid rgba(239,68,68,0.4)' }
    : { background: 'linear-gradient(90deg, rgba(26,15,8,0.9), rgba(13,7,4,0.9))', border: '1px solid rgba(90,66,41,0.4)' }

  const textColor = isPolice ? '#93c5fd' : isThief ? '#fca5a5' : '#ffe58f'
  const labelColor = isPolice ? '#3b82f6' : isThief ? '#ef4444' : '#c89f59'

  return (
    <div className="w-full rounded-lg px-4 py-2.5 flex items-center justify-between" style={{
      ...bgStyle,
      boxShadow: '0 4px 16px rgba(0,0,0,0.6)',
    }}>
      <div className="flex items-center gap-3">
        <span className="text-[10px] font-serif uppercase tracking-widest" style={{ color: labelColor }}>
          {t.game.yourRole}
        </span>
        <span className="font-serif font-black text-base tracking-wider" style={{ color: textColor }}>
          {t.roles[role.toLowerCase() as keyof typeof t.roles] || role}
        </span>
      </div>
      {(points ?? 0) > 0 && (
        <span className="text-[10px] font-serif tracking-wider" style={{ color: labelColor }}>
          {points} {t.game.pointsPerRound}
        </span>
      )}
    </div>
  )
}

import { useMemo, useState, useEffect } from 'react'
import type { Player } from '../../types/game'
import { avatarKeyToUrl } from '../../utils/avatarMap'
import { useProfileStore } from '../../stores/profileStore'
import { useGameStore } from '../../stores/gameStore'
import { useVoiceStore } from '../../stores/voiceStore'
import { useLanguageStore } from '../../stores/languageStore'
import mainGameMobile from '../../assets/main_game.webp'
import mainGameDesktop from '../../assets/main_game_desktop.webp'

interface GameTableLayoutProps {
  players: Player[]
  myPlayerId: string | null
  policeId: string | null
  /** Currently selected player (for police selection highlight) */
  selectedPlayerId?: string | null
  /** Called when a player seat is tapped */
  onPlayerTap?: (playerId: string) => void
  /** Whether player tapping is enabled */
  interactable?: boolean
  /** Center content (e.g. role info, round info, etc.) */
  centerContent?: React.ReactNode
  /** Bottom bar content (role card, action buttons, etc.) */
  bottomContent?: React.ReactNode
  /** Top bar content (round info, etc.) */
  topContent?: React.ReactNode
}

export default function GameTableLayout({
  players,
  myPlayerId,
  policeId,
  selectedPlayerId,
  onPlayerTap,
  interactable = false,
  centerContent,
  bottomContent,
  topContent,
}: GameTableLayoutProps) {
  const { avatar: myAvatar } = useProfileStore()
  const pointers = useGameStore((s) => s.pointers)
  const emotes = useGameStore((s) => s.emotes)
  const speakingPlayers = useVoiceStore((s) => s.speakingPlayers)
  const remoteMutedMap = useVoiceStore((s) => s.remoteMutedMap)
  const isMeMuted = useVoiceStore((s) => s.isMuted)
  const { t } = useLanguageStore()
  const [now, setNow] = useState(Date.now())

  // Force re-render periodically to clear old emotes
  useEffect(() => {
    const interval = setInterval(() => setNow(Date.now()), 1000)
    return () => clearInterval(interval)
  }, [])

  // Calculate positions for each player around the circle
  const playerPositions = useMemo(() => {
    const count = players.length
    if (count === 0) return []

    return players.map((player, index) => {
      // Start from top (-90deg) and go clockwise
      const angle = ((index / count) * 2 * Math.PI) - (Math.PI / 2)
      // Use percentage-based positioning (50% = center)
      const radiusX = 38 // % from center
      const radiusY = 34 // % from center (slightly less for oval)
      const x = 50 + radiusX * Math.cos(angle)
      const y = 50 + radiusY * Math.sin(angle)
      return { player, x, y, angle }
    })
  }, [players])

  return (
    <div className="min-h-screen relative overflow-hidden bg-[#0a0604]">
      {/* Backgrounds */}
      <div
        className="hidden md:block absolute inset-0 bg-cover bg-center"
        style={{ backgroundImage: `url(${mainGameDesktop})` }}
      />
      <div
        className="md:hidden absolute inset-0 bg-cover bg-center"
        style={{ backgroundImage: `url(${mainGameMobile})` }}
      />

      {/* Dark overlay for readability */}
      <div className="absolute inset-0 bg-black/20" />

      {/* Top Content */}
      {topContent && (
        <div className="absolute top-0 left-0 right-0 z-30 pt-3 pb-2 px-4 flex justify-center">
          {topContent}
        </div>
      )}

      {/* ═══ THE TABLE ═══ */}
      <div className="relative z-10 min-h-screen flex items-center justify-center p-4">
        <div className="relative w-full max-w-[500px] aspect-square">

          {/* Table circle visual (subtle overlay to define the table area) */}
          <div className="absolute inset-[8%] rounded-full pointer-events-none" style={{
            background: 'radial-gradient(circle, rgba(90,55,20,0.08) 0%, transparent 70%)',
          }} />

          {/* Center content */}
          <div className="absolute inset-0 flex items-center justify-center pointer-events-none z-20">
            <div className="flex flex-col items-center pointer-events-auto">
              {centerContent || <DefaultCenterContent />}
            </div>
          </div>



          {/* Player seats */}
          {playerPositions.map(({ player, x, y }) => {
            const isMe = player.id === myPlayerId
            const isPolice = player.id === policeId
            const isSelected = player.id === selectedPlayerId
            const resolvedAvatar = avatarKeyToUrl(player.avatarKey) || (isMe ? myAvatar : null)
            const activeEmote = emotes[player.id]
            const isEmoting = activeEmote && (now - activeEmote.timestamp < 3500)
            const isSpeaking = speakingPlayers[player.id]
            const playerIsMuted = isMe ? isMeMuted : (remoteMutedMap[player.id] ?? false)

            return (
              <div
                key={player.id}
                className="absolute z-20"
                style={{
                  left: `${x}%`,
                  top: `${y}%`,
                  transform: 'translate(-50%, -50%)',
