                        ? 'bg-[#5ce65c] shadow-[0_0_6px_rgba(92,230,92,0.6)]'
                        : 'bg-[#e65c5c]'
                    }`} />
                    
                    {/* Muted indicator */}
                    {playerIsMuted && (
                      <div className="absolute -top-1 -right-1 bg-red-500/90 rounded-full p-0.5 border border-red-900 shadow-sm z-30">
                        <svg className="w-3 h-3 text-white" viewBox="0 0 24 24" fill="currentColor">
                          <path d="M19 11h-1.7c0 .74-.16 1.43-.43 2.05l1.23 1.23c.56-.98.9-2.09.9-3.28zm-4.02 3.28c-.91.71-2.04 1.16-3.28 1.16-2.97 0-5.38-2.4-5.38-5.38H4.62c0 3.56 2.67 6.48 6.13 6.91V21h2.5v-4.03c1.02-.13 1.97-.47 2.82-.96l-1.09-1.09zM11.7 8.01L6.68 3 5.27 4.41 9 8.14v3.86c0 .48.09.94.25 1.37l1.01-1.01v-1.4h1.44l2.84 2.84 1.41-1.41L11.7 8.01zM11.7 3.5c1.47 0 2.68 1.21 2.68 2.68v4.3l-2.68-2.68v-4.3z"/>
                        </svg>
                      </div>
                    )}
                    
                    {/* Vote Badges (Who is pointing at me) */}
                    {(() => {
                      const pointersToMe = Object.entries(pointers)
                        .filter(([_, toId]) => toId === player.id)
                        .map(([fromId]) => players.find(p => p.id === fromId))
                        .filter(Boolean) as Player[]
                        
                      if (pointersToMe.length === 0) return null;
                      
                      return (
                        <div className="absolute top-0 right-full mr-0.5 sm:mr-1 flex flex-row-reverse -space-x-1.5 -space-x-reverse pointer-events-none z-50 animate-in zoom-in-50 duration-200" style={{ filter: 'drop-shadow(0 2px 4px rgba(0,0,0,0.8))' }}>
                          {pointersToMe.map((pointerPlayer, i) => {
                            const pointerAvatarUrl = avatarKeyToUrl(pointerPlayer.avatarKey) || (pointerPlayer.id === myPlayerId ? myAvatar : null)
                            return (
                              <div key={pointerPlayer.id} className="w-5 h-5 sm:w-6 sm:h-6 rounded-full border border-[#d4af37] bg-[#0d0704] flex items-center justify-center overflow-hidden" style={{ zIndex: 20 - i, boxShadow: '0 0 5px rgba(212,175,55,0.5)' }}>
                                {pointerAvatarUrl ? (
                                  <img src={pointerAvatarUrl} className="w-full h-full object-cover" />
                                ) : (
                                  <svg className="w-full h-full text-[#c89f59] p-0.5" viewBox="0 0 24 24" fill="currentColor"><path d="M12 12c2.21 0 4-1.79 4-4s-1.79-4-4-4-4 1.79-4 4 1.79 4 4 4zm0 2c-2.67 0-8 1.34-8 4v2h16v-2c0-2.66-5.33-4-8-4z"/></svg>
                                )}
                              </div>
                            )
                          })}
                        </div>
                      )
                    })()}
                  </div>

                  {/* Player name */}
                  <div className="mt-1 px-2 py-0.5 rounded-md max-w-[80px] sm:max-w-[90px]" style={{
                    background: 'rgba(13,7,4,0.85)',
                    border: '1px solid rgba(90,66,41,0.3)',
                  }}>
                    <span className={`text-[9px] sm:text-[10px] font-serif font-bold tracking-wider truncate block text-center ${
                      isMe ? 'text-[#ffe58f]' : 'text-[#c89f59]'
                    }`}>
                      {player.username}
                      {isMe && <span className="text-[#8a6b20] ml-0.5">{t.game.you}</span>}
                    </span>
                  </div>
                </button>
              </div>
            )
          })}
        </div>
      </div>

      {/* Bottom Content */}
      {bottomContent && (
        <div className="fixed bottom-0 left-0 right-0 z-30 pb-4 px-4 flex flex-col items-center gap-2 pointer-events-none">
          <div className="pointer-events-auto w-full max-w-[420px]">
            {bottomContent}
          </div>
        </div>
      )}

      <style>{`
        @keyframes dashMove {
          from { stroke-dashoffset: 14; }
          to { stroke-dashoffset: 0; }
        }
        @keyframes floatUpAndFade {
          0% { opacity: 0; transform: translate(-50%, 10px) scale(0.5); }
          15% { opacity: 1; transform: translate(-50%, -10px) scale(1.2); }
          30% { transform: translate(-50%, -5px) scale(1); }
          80% { opacity: 1; transform: translate(-50%, -20px) scale(1); }
          100% { opacity: 0; transform: translate(-50%, -40px) scale(0.8); }
        }
      `}</style>
    </div>
  )
}

