import { useState, useEffect } from 'react'
import { useGameStore } from '../../stores/gameStore'
import { avatarKeyToUrl } from '../../utils/avatarMap'
import { useProfileStore } from '../../stores/profileStore'
import { supabase } from '../../lib/supabase'
import { useLanguageStore } from '../../stores/languageStore'

interface PoliceSelectionProps {
  selectedId: string | null
  onClearSelection: () => void
  timeLeft: number
}

export default function PoliceSelection({ selectedId, onClearSelection, timeLeft }: PoliceSelectionProps) {
  const room = useGameStore((s) => s.room)
  const players = useGameStore((s) => s.players)
  const myPlayerId = useGameStore((s) => s.myPlayerId)
  const policeId = useGameStore((s) => s.policeId)
  const { avatar: myAvatar } = useProfileStore()
  const { t } = useLanguageStore()

  const [submitted, setSubmitted] = useState(false)
  const [loading, setLoading] = useState(false)
  const [error, setError] = useState<string | null>(null)

  if (myPlayerId !== policeId) return null

  const selectedPlayer = players.find((p) => p.id === selectedId)

  async function handleAccuse(forcedAccuseId?: string) {
    const targetId = typeof forcedAccuseId === 'string' ? forcedAccuseId : selectedId
    if (!room || !targetId) return
    setLoading(true)
    setError(null)
    try {
      const { data: { session } } = await supabase.auth.getSession()
      if (!session) { setError('Not authenticated'); return }
      const response = await supabase.functions.invoke('make-accusation', {
        body: { roomId: room.id, accusedPlayerId: targetId },
        headers: { Authorization: `Bearer ${session.access_token}` },
      })
      if (response.error) {
        let msg = response.error.message
        if ('context' in response.error && typeof (response.error as any).context?.json === 'function') {
          try {
            const body = await (response.error as any).context.json()
            if (body && body.error) {
              msg = body.error
            }
          } catch (_) {}
        }
        setError(msg)
      } else {
        setSubmitted(true)
      }
    } catch (err) {
      setError(err instanceof Error ? err.message : 'Failed to submit accusation')
    } finally {
      setLoading(false)
    }
  }

  useEffect(() => {
    if (timeLeft === 0 && !submitted && !loading) {
      // Auto-accuse oneself to guarantee the Thief wins on timeout
      handleAccuse(myPlayerId!)
    }
  }, [timeLeft, submitted, loading, myPlayerId])

  if (submitted) {
    return (
      <div className="w-full rounded-lg py-3 text-center" style={{
        background: 'linear-gradient(180deg, rgba(120,53,15,0.8), rgba(80,30,10,0.9))',
        border: '1px solid rgba(251,146,60,0.3)',
        boxShadow: '0 4px 12px rgba(0,0,0,0.5)',
      }}>
        <span className="font-serif text-orange-300 text-xs sm:text-sm font-bold tracking-wider animate-pulse">
          {t.game.accusationSubmitted}
        </span>
      </div>
    )
  }

  // ─── Confirmation dialog ───
  if (selectedId && selectedPlayer) {
    const resolvedAvatar = avatarKeyToUrl(selectedPlayer.avatarKey) || (selectedPlayer.id === myPlayerId ? myAvatar : null)

    return (
      <div className="w-full rounded-xl overflow-hidden" style={{
        background: 'linear-gradient(180deg, rgba(26,15,8,0.95), rgba(13,7,4,0.95))',
        border: '1px solid rgba(90,66,41,0.5)',
        boxShadow: '0 8px 24px rgba(0,0,0,0.7)',
      }}>
        <div className="px-4 py-4 flex flex-col items-center gap-3">
          {/* Target avatar */}
          <div className="w-14 h-14 rounded-full overflow-hidden border-2 border-[#c89f59] shadow-lg" style={{
            boxShadow: '0 0 20px rgba(212,175,55,0.3)',
          }}>
            {resolvedAvatar ? (
              <img src={resolvedAvatar} alt={selectedPlayer.username} className="w-full h-full object-cover" />
            ) : (
              <div className="w-full h-full bg-[#1a0f08] flex items-center justify-center">
                <svg className="w-7 h-7 text-[#c89f59] opacity-50" viewBox="0 0 24 24" fill="currentColor">
                  <path d="M12 12c2.21 0 4-1.79 4-4s-1.79-4-4-4-4 1.79-4 4 1.79 4 4 4zm0 2c-2.67 0-8 1.34-8 4v2h16v-2c0-2.66-5.33-4-8-4z"/>
                </svg>
              </div>
            )}
          </div>

          <p className="font-serif text-sm text-[#c89f59] text-center">
            {t.game.accusePrompt.replace('{{name}}', selectedPlayer.username)}
          </p>

          <div className="flex gap-3 w-full">
            {/* Cancel */}
            <button
              onClick={onClearSelection}
              disabled={loading}
              className="flex-1 rounded-lg py-2.5 transition-all active:scale-95 focus:outline-none disabled:opacity-50"
              style={{
                background: 'linear-gradient(180deg, rgba(60,42,26,0.9), rgba(30,20,10,0.9))',
                border: '1px solid rgba(90,66,41,0.4)',
                color: '#c89f59',
              }}
            >
              <span className="font-serif font-bold text-xs uppercase tracking-widest">{t.common.cancel}</span>
            </button>

            {/* Confirm */}
            <button
              onClick={() => handleAccuse()}
              disabled={loading}
              className="flex-[2] relative group rounded-lg active:scale-95 transition-all focus:outline-none disabled:opacity-50"
            >
              <div className="absolute -inset-[1px] rounded-lg opacity-60 group-hover:opacity-80 transition-opacity" style={{
                background: 'linear-gradient(180deg, #ffe58f, #a67c00)',
              }} />
              <div className="relative rounded-lg py-2.5 flex items-center justify-center" style={{
                background: 'linear-gradient(180deg, #c9a033 0%, #9a7220 40%, #7a5a18 100%)',
                boxShadow: 'inset 0 1px 1px rgba(255,229,143,0.5), inset 0 -2px 4px rgba(0,0,0,0.4)',
              }}>
                <span className="font-serif font-black text-xs tracking-[0.15em] uppercase" style={{
                  background: 'linear-gradient(180deg, #fff8e1, #ffe58f, #d4af37)',
                  WebkitBackgroundClip: 'text',
                  WebkitTextFillColor: 'transparent',
                }}>
                  {loading ? t.game.submittingAccusation : t.game.confirmAccusation}
                </span>
              </div>
            </button>
          </div>
        </div>
      </div>
    )
  }

  // ─── Empty state (waiting for selection) ───
  return (
    <div className="w-full">
      <div className="w-full rounded-lg py-3 text-center" style={{
        background: 'linear-gradient(180deg, rgba(13,7,4,0.9), rgba(26,15,8,0.85))',
        border: '1px solid rgba(90,66,41,0.3)',
        boxShadow: '0 4px 12px rgba(0,0,0,0.5)',
      }}>
        <span className="font-serif text-[#c89f59] text-xs sm:text-sm italic tracking-wide animate-pulse">
          {t.game.tapToAccuse}
        </span>
      </div>
      {error && (
        <div className="mt-2 text-center">
          <span className="text-[#ff6b6b] font-serif text-xs font-bold">{error}</span>
        </div>
      )}
    </div>
  )
}

import { useState, useEffect } from 'react'
import { useGameStore } from '../../stores/gameStore'
import AnimatedRoleCard from './AnimatedRoleCard'

export default function RoleReveal() {
  const myRole = useGameStore((s) => s.myRole)
  const myRolePoints = useGameStore((s) => s.myRolePoints)
  const [visible, setVisible] = useState(false)
  const [dismissed, setDismissed] = useState(false)

  // Show overlay when role arrives
  useEffect(() => {
    if (myRole && !dismissed) {
      setVisible(true)
    }
  }, [myRole, dismissed])

  // Reset dismissed state when role changes (new round)
  useEffect(() => {
    setDismissed(false)
  }, [myRole])

  if (!visible || !myRole) return null

  return (
    <AnimatedRoleCard 
      role={myRole} 
      points={myRolePoints} 
      onDismiss={() => {
        setVisible(false)
        setDismissed(true)
      }} 
    />
  )
}

import { useState, useEffect } from 'react'
import { useGameStore } from '../../stores/gameStore'
import { avatarKeyToUrl } from '../../utils/avatarMap'
import { useProfileStore } from '../../stores/profileStore'
import { playWin, playLose } from '../../utils/sounds'
import { supabase } from '../../lib/supabase'
import { useLanguageStore } from '../../stores/languageStore'
import mainGameMobile from '../../assets/main_game.webp'
import mainGameDesktop from '../../assets/main_game_desktop.webp'

export default function RoundResult() {
  const room = useGameStore((s) => s.room)
  const players = useGameStore((s) => s.players)
  const myPlayerId = useGameStore((s) => s.myPlayerId)
  const lastResult = useGameStore((s) => s.lastResult)
  const { avatar: myAvatar } = useProfileStore()
  const { t } = useLanguageStore()

  const [loading, setLoading] = useState(false)
  const [error, setError] = useState<string | null>(null)

  const isHost = room?.hostId === myPlayerId
  const hostPlayer = players.find(p => p.id === room?.hostId)
  const isHostDisconnected = hostPlayer && !hostPlayer.isConnected
  const canAdvance = isHost || isHostDisconnected
  const isFinalRound = room ? room.currentRound >= room.totalRounds : false

  async function handleNextRound() {
    if (!room) return
    setLoading(true)
    setError(null)
    try {
      const { data: { session } } = await supabase.auth.getSession()
      if (!session) { setError('Not authenticated'); return }
      const response = await supabase.functions.invoke('next-round', {
        body: { roomId: room.id },
        headers: { Authorization: `Bearer ${session.access_token}` },
      })
      if (response.error) {
        setError(response.error.message || 'Failed to proceed')
      }
    } catch (err) {
      setError(err instanceof Error ? err.message : 'Failed to proceed')
    } finally {
      setLoading(false)
    }
  }

  async function handleEndGame() {
    if (!room) return
    setLoading(true)
    setError(null)
    try {
      const { data: { session } } = await supabase.auth.getSession()
      if (!session) { setError('Not authenticated'); return }
      const response = await supabase.functions.invoke('next-round', {
        body: { roomId: room.id },
        headers: { Authorization: `Bearer ${session.access_token}` },
      })
      if (response.error) {
        setError(response.error.message || 'Failed to end game')
      }
    } catch (err) {
      setError(err instanceof Error ? err.message : 'Failed to end game')
    } finally {
      setLoading(false)
    }
  }

  useEffect(() => {
    if (!lastResult) return
    if (lastResult.correctGuess) {
      playWin()
    } else {
      playLose()
    }
  }, [lastResult?.correctGuess])

  if (!room || !lastResult) return null

  const thiefPlayer = players.find((p) => p.id === lastResult.thiefId)
  const accusedPlayer = players.find((p) => p.id === lastResult.accusedId)
  const policePlayer = players.find((p) => p.id === lastResult.policeId)
  const sortedPlayers = [...players].sort((a, b) => b.score - a.score)

  return (
    <div className="min-h-screen relative overflow-hidden bg-[#0a0604]">
      {/* Backgrounds */}
      <div className="hidden md:block absolute inset-0 bg-cover bg-center opacity-60"
        style={{ backgroundImage: `url(${mainGameDesktop})` }} />
      <div className="md:hidden absolute inset-0 bg-cover bg-center opacity-60"
        style={{ backgroundImage: `url(${mainGameMobile})` }} />
      <div className="absolute inset-0 bg-black/30" />

      {/* Content */}
      <div className="relative z-10 min-h-screen flex flex-col items-center justify-center p-4 py-12">

        {/* ═══ Result Card (The Plate) ═══ */}
        <div className="w-full max-w-[460px]" style={{ animation: 'resultReveal 0.7s cubic-bezier(0.16, 1, 0.3, 1) forwards' }}>

          {/* Crown */}
          <div className="flex justify-center mb-[-12px] relative z-30">
            <svg width="48" height="36" viewBox="0 0 48 36" fill="none">
              <path d="M24 0L28 14L36 6L32 20H16L12 6L20 14L24 0Z" fill="url(#crownResult)" stroke="#5a3e15" strokeWidth="1"/>
              <circle cx="24" cy="4" r="2.5" fill="#ffe58f" stroke="#a67c00" strokeWidth="0.5"/>
              <circle cx="13" cy="8" r="1.8" fill="#ffe58f" stroke="#a67c00" strokeWidth="0.5"/>
              <circle cx="35" cy="8" r="1.8" fill="#ffe58f" stroke="#a67c00" strokeWidth="0.5"/>
              <rect x="14" y="20" width="20" height="4" rx="1" fill="url(#crownResult)" stroke="#5a3e15" strokeWidth="0.5"/>
              <defs>
                <linearGradient id="crownResult" x1="0" y1="0" x2="0" y2="1">
                  <stop offset="0%" stopColor="#ffe58f"/><stop offset="50%" stopColor="#d4af37"/><stop offset="100%" stopColor="#8a6b20"/>
                </linearGradient>
              </defs>
            </svg>
          </div>

          {/* Layer 1 */}
          <div className="rounded-[22px] p-[3px]" style={{ background: 'linear-gradient(145deg, #2a1a0a, #0d0805, #2a1a0a)' }}>
            {/* Layer 2 */}
            <div className="rounded-[19px] p-[4px]" style={{ background: 'linear-gradient(160deg, #d4af37 0%, #a67c00 20%, #593d19 40%, #a67c00 60%, #d4af37 80%, #8a6b20 100%)' }}>
              {/* Layer 3 */}
              <div className="rounded-[15px] p-[2px]" style={{ background: 'linear-gradient(145deg, #1a1008, #0a0604)' }}>
                {/* Layer 4 */}
                <div className="rounded-[13px] p-[1px]" style={{ background: 'linear-gradient(160deg, #c89f59 0%, #5a4229 30%, #c89f59 60%, #5a4229 100%)' }}>
                  {/* Layer 5: Body */}
                  <div className="rounded-[12px] relative overflow-hidden" style={{ background: 'linear-gradient(180deg, #2c1a0e 0%, #1a0f08 30%, #140b06 70%, #0d0704 100%)' }}>

                    {/* Leather texture */}
                    <div className="absolute inset-0 pointer-events-none opacity-60" style={{
                      background: `radial-gradient(ellipse at 30% 20%, rgba(139,90,43,0.25) 0%, transparent 50%),
                        radial-gradient(ellipse at 70% 80%, rgba(139,90,43,0.15) 0%, transparent 50%),
                        radial-gradient(ellipse at 50% 50%, rgba(90,55,20,0.3) 0%, transparent 70%)`
                    }} />
                    <div className="absolute inset-0 pointer-events-none" style={{
                      boxShadow: 'inset 0 0 80px rgba(0,0,0,0.9), inset 0 0 30px rgba(0,0,0,0.5)'
                    }} />

                    {/* Content */}
                    <div className="relative z-10 px-6 sm:px-8 pt-8 pb-5">

                      {/* Round label */}
                      <SectionDivider text={t.game.roundResult.replace('{{round}}', lastResult.roundNumber.toString())} />

                      {/* Result Banner */}
                      <div className="flex flex-col items-center mt-4 mb-6">
                        {lastResult.correctGuess ? (
                          <>
                            <h2 className="font-serif font-black text-3xl sm:text-4xl tracking-wider mb-2" style={{
                              background: 'linear-gradient(180deg, #86efac, #22c55e, #16a34a)',
                              WebkitBackgroundClip: 'text',
                              WebkitTextFillColor: 'transparent',
                              filter: 'drop-shadow(0 3px 8px rgba(34,197,94,0.4))',
                            }}>
                              {t.game.thiefCaught}
                            </h2>
                            <p className="font-serif text-sm text-[#c89f59] text-center">
                              {t.game.correctlyAccused
                                .replace('{{police}}', policePlayer?.username || 'Police')
                                .replace('{{accused}}', accusedPlayer?.username || 'Thief')}
                            </p>
                          </>
                        ) : (
                          <>
                            <h2 className="font-serif font-black text-3xl sm:text-4xl tracking-wider mb-2" style={{
                              background: 'linear-gradient(180deg, #fca5a5, #ef4444, #dc2626)',
                              WebkitBackgroundClip: 'text',
                              WebkitTextFillColor: 'transparent',
                              filter: 'drop-shadow(0 3px 8px rgba(239,68,68,0.4))',
                            }}>
                              {t.game.thiefEscaped}
                            </h2>
                            <p className="font-serif text-sm text-[#c89f59] text-center">
                              {t.game.wronglyAccused
                                .replace('{{police}}', policePlayer?.username || 'Police')
                                .replace('{{accused}}', accusedPlayer?.username || 'Player')
                                .replace('{{role}}', t.roles[lastResult.accusedRole.toLowerCase() as keyof typeof t.roles] || lastResult.accusedRole)}
                            </p>
                            <p className="font-serif text-xs text-[#8a6b20] mt-1">
                              {t.game.theThiefWas.replace('{{thief}}', thiefPlayer?.username || 'Thief')}
                            </p>
                          </>
                        )}
                      </div>

                      {/* Scoreboard */}
                      <SectionDivider text={t.game.scores} />
                      <div className="space-y-1.5 mt-2 mb-4 max-h-[30vh] overflow-y-auto">
                        {sortedPlayers.map((player, idx) => {
                          const resolvedAvatar = avatarKeyToUrl(player.avatarKey) || (player.id === myPlayerId ? myAvatar : null)
                          const isMe = player.id === myPlayerId
                          const medal = idx === 0 ? '🥇' : idx === 1 ? '🥈' : idx === 2 ? '🥉' : null

                          return (
                            <div key={player.id} className="relative rounded-lg p-[1px]" style={{
                              background: isMe
                                ? 'linear-gradient(180deg, #d4af37, #5a3e15)'
                                : 'linear-gradient(180deg, #5a3e15, #2a1a0a)',
                            }}>
                              <div className="flex items-center justify-between px-3 py-2 rounded-[7px]" style={{
                                background: 'linear-gradient(90deg, #1a0f08, #2c1a0e)',
                              }}>
                                <div className="flex items-center gap-2.5">
                                  <span className="text-[11px] font-serif font-bold text-[#5a3e15] w-5 text-center">
                                    {medal || `#${idx + 1}`}
                                  </span>
                                  {/* Avatar */}
                                  <div className="w-7 h-7 rounded-full overflow-hidden border border-[#5a3e15] flex-shrink-0" style={{ background: '#0d0704' }}>
                                    {resolvedAvatar ? (
                                      <img src={resolvedAvatar} alt="" className="w-full h-full object-cover" />
                                    ) : (
                                      <div className="w-full h-full flex items-center justify-center">
                                        <svg className="w-3.5 h-3.5 text-[#c89f59] opacity-50" viewBox="0 0 24 24" fill="currentColor">
                                          <path d="M12 12c2.21 0 4-1.79 4-4s-1.79-4-4-4-4 1.79-4 4 1.79 4 4 4zm0 2c-2.67 0-8 1.34-8 4v2h16v-2c0-2.66-5.33-4-8-4z"/>
                                        </svg>
                                      </div>
                                    )}
                                  </div>
                                  <span className={`font-serif font-bold text-sm tracking-wider ${isMe ? 'text-[#ffe58f]' : 'text-[#c89f59]'}`}>
                                    {player.username}
                                    {isMe && <span className="text-[#8a6b20] text-[10px] ml-1">{t.game.you}</span>}
                                  </span>
                                </div>
                                <span className="font-serif font-black text-sm tracking-wider" style={{
                                  background: 'linear-gradient(180deg, #ffe58f, #d4af37)',
                                  WebkitBackgroundClip: 'text',
                                  WebkitTextFillColor: 'transparent',
                                }}>
                                  {player.score}
                                </span>
                              </div>
                            </div>
                          )
                        })}
                      </div>

                      {/* Host Actions (or fallback if host disconnects) */}
                      {canAdvance && (
                        <div className="mt-2">
                          {isFinalRound ? (
                            <button
                              onClick={handleEndGame}
                              disabled={loading}
                              className="w-full relative group rounded-lg active:scale-[0.97] transition-all focus:outline-none disabled:opacity-50"
                            >
                              <div className="absolute -inset-[1px] rounded-lg opacity-60 group-hover:opacity-80 transition-opacity" style={{
                                background: 'linear-gradient(180deg, #c084fc, #7c3aed)',
                              }} />
                              <div className="relative rounded-lg py-3.5 flex items-center justify-center" style={{
                                background: 'linear-gradient(180deg, #7c3aed 0%, #5b21b6 40%, #4c1d95 100%)',
                                boxShadow: 'inset 0 1px 1px rgba(192,132,252,0.4), inset 0 -2px 4px rgba(0,0,0,0.4), 0 6px 20px rgba(0,0,0,0.7)',
                              }}>
                                <span className="font-serif font-black text-[14px] tracking-[0.15em] uppercase" style={{
                                  background: 'linear-gradient(180deg, #f3e8ff, #c084fc, #a855f7)',
                                  WebkitBackgroundClip: 'text',
                                  WebkitTextFillColor: 'transparent',
                                }}>
                                  {loading ? t.game.loading : t.game.seeFinalResults}
                                </span>
                              </div>
                            </button>
                          ) : (
                            <button
                              onClick={handleNextRound}
                              disabled={loading}
                              className="w-full relative group rounded-lg active:scale-[0.97] transition-all focus:outline-none disabled:opacity-50"
                            >
                              <div className="absolute -inset-[1px] rounded-lg opacity-60 group-hover:opacity-80 transition-opacity" style={{
                                background: 'linear-gradient(180deg, #ffe58f, #a67c00)',
                              }} />
                              <div className="relative rounded-lg py-3.5 flex items-center justify-center gap-2" style={{
                                background: 'linear-gradient(180deg, #c9a033 0%, #9a7220 40%, #7a5a18 100%)',
                                boxShadow: 'inset 0 1px 1px rgba(255,229,143,0.5), inset 0 -2px 4px rgba(0,0,0,0.4), 0 6px 20px rgba(0,0,0,0.7)',
                              }}>
                                <span className="font-serif font-black text-[14px] tracking-[0.15em] uppercase" style={{
                                  background: 'linear-gradient(180deg, #fff8e1, #ffe58f, #d4af37)',
                                  WebkitBackgroundClip: 'text',
                                  WebkitTextFillColor: 'transparent',
                                }}>
                                  {loading ? t.game.loading : `${t.game.nextRound} (${room.currentRound + 1}/${room.totalRounds})`}
                                </span>
                              </div>
                            </button>
                          )}
                        </div>
                      )}

                      {!canAdvance && (
                        <div className="w-full text-center py-2 mt-2">
                          <span className="text-[#c89f59] font-serif text-xs italic tracking-wide">
                            {t.game.waitingForHostToContinue}
                          </span>
                        </div>
                      )}

                      {error && (
                        <div className="mt-2 text-center">
                          <span className="text-[#ff6b6b] font-serif text-xs font-bold">{error}</span>
                        </div>
                      )}
                    </div>
                  </div>
                </div>
              </div>
            </div>
          </div>
        </div>
      </div>

      <style>{`
        @keyframes resultReveal {
          0% { opacity: 0; transform: scale(0.9) translateY(30px); }
          100% { opacity: 1; transform: scale(1) translateY(0); }
        }
      `}</style>
    </div>
  )
}

function SectionDivider({ text }: { text: string }) {
  return (
    <div className="flex items-center justify-center gap-3 w-full">
      <div className="flex-1 h-[1px]" style={{ background: 'linear-gradient(90deg, transparent, rgba(200,159,89,0.4))' }} />
      <span className="font-serif font-bold text-[11px] sm:text-[13px] uppercase tracking-[0.25em] text-[#c89f59] whitespace-nowrap drop-shadow-md">
        {text}
      </span>
      <div className="flex-1 h-[1px]" style={{ background: 'linear-gradient(90deg, rgba(200,159,89,0.4), transparent)' }} />
    </div>
  )
}

import { useState } from 'react'
import { useNavigate } from 'react-router-dom'
import { useGameStore } from '../../stores/gameStore'
import { useProfileStore } from '../../stores/profileStore'
import { useSoundStore } from '../../stores/soundStore'
import { avatarKeyToUrl } from '../../utils/avatarMap'
import { playClick } from '../../utils/sounds'
import { supabase } from '../../lib/supabase'
import { useLanguageStore } from '../../stores/languageStore'
import lobbyBgMobile from '../../assets/lobby.webp'
import lobbyBgDesktop from '../../assets/lobby_desktop.webp'
import bgMusic from '../../assets/sound/game_bg.mp3'

export default function WaitingLobby() {
  const navigate = useNavigate()
  const room = useGameStore((s) => s.room)
  const players = useGameStore((s) => s.players)
  const myPlayerId = useGameStore((s) => s.myPlayerId)
  const resetStore = useGameStore((s) => s.reset)
  const { avatar: myAvatar } = useProfileStore()
  const { t } = useLanguageStore()

  const [loading, setLoading] = useState(false)
  const [error, setError] = useState<string | null>(null)
  const [copied, setCopied] = useState(false)

  const isHost = room?.hostId === myPlayerId
  const playerCount = players.length
  const canStart = isHost && playerCount >= 3
  const { isMuted } = useSoundStore()

  async function handleStartGame() {
    playClick()
    if (!room) return
    setLoading(true)
    setError(null)

    try {
      const { data: { session } } = await supabase.auth.getSession()
      if (!session) {
        setError('Not authenticated')
        return
      }

      const response = await supabase.functions.invoke('start-game', {
        body: { roomId: room.id },
        headers: { Authorization: `Bearer ${session.access_token}` },
      })

      if (response.error) {
        let msg = response.error.message
        if ('context' in response.error && typeof (response.error as any).context?.json === 'function') {
          try {
            const body = await (response.error as any).context.json()
            if (body && body.error) {
              msg = body.error
            }
          } catch (_) {}
        }
        setError(msg || 'Failed to start game')
      }
    } catch (err) {
      setError(err instanceof Error ? err.message : 'Failed to start game')
    } finally {
      setLoading(false)
    }
  }

  function handleCopy() {
    playClick()
    if (!room) return
    navigator.clipboard.writeText(room.code)
    setCopied(true)
    setTimeout(() => setCopied(false), 2000)
  }

  async function handleExit() {
    playClick()
    if (!room) return
    setLoading(true)
    try {
      const { data: { session } } = await supabase.auth.getSession()
      if (session) {
        await supabase.functions.invoke('leave-room', {
          body: { roomId: room.id },
          headers: { Authorization: `Bearer ${session.access_token}` },
        })
      }
    } catch (e) {
      console.error("Error leaving room:", e)
    } finally {
      resetStore()
      navigate('/home')
    }
  }

  if (!room) return null

  const roomCodeChars = room.code.split('')

  return (
    <div className="min-h-screen relative overflow-hidden bg-slate-950 flex flex-col items-center justify-center p-4">
      {/* Background Music */}
      <audio src={bgMusic} autoPlay loop muted={isMuted} />
      
      {/* Backgrounds */}
      <div 
        className="hidden md:block absolute inset-0 bg-cover bg-center opacity-80" 
        style={{ backgroundImage: `url(${lobbyBgDesktop})` }} 
      />
      <div 
        className="md:hidden absolute inset-0 bg-cover bg-center opacity-80" 
        style={{ backgroundImage: `url(${lobbyBgMobile})` }} 
      />

      {/* Exit Button */}
      <button
        onClick={handleExit}
        disabled={loading}
        className="absolute top-4 left-4 z-50 flex items-center justify-center w-10 h-10 rounded-full bg-black/50 backdrop-blur-md border border-white/10 hover:bg-red-900/50 hover:border-red-500/50 transition-all text-white/80 hover:text-red-400"
        title="Leave Room"
      >
        <svg className="w-5 h-5" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2">
          <path strokeLinecap="round" strokeLinejoin="round" d="M17 16l4-4m0 0l-4-4m4 4H7m6 4v1a3 3 0 01-3 3H6a3 3 0 01-3-3V7a3 3 0 013-3h4a3 3 0 013 3v1" />
        </svg>
      </button>
      
      {/* ── THE PLATE ── */}
      <div className="w-full max-w-[540px] relative z-10 animate-in zoom-in-95 duration-500">
        
        {/* Crown on top */}
        <div className="absolute -top-5 left-1/2 -translate-x-1/2 z-30">
          <svg width="48" height="36" viewBox="0 0 48 36" fill="none">
            <path d="M24 0L28 14L36 6L32 20H16L12 6L20 14L24 0Z" fill="url(#crownGoldLobby)" stroke="#5a3e15" strokeWidth="1"/>
            <circle cx="24" cy="4" r="2.5" fill="#ffe58f" stroke="#a67c00" strokeWidth="0.5"/>
            <circle cx="13" cy="8" r="1.8" fill="#ffe58f" stroke="#a67c00" strokeWidth="0.5"/>
            <circle cx="35" cy="8" r="1.8" fill="#ffe58f" stroke="#a67c00" strokeWidth="0.5"/>
            <rect x="14" y="20" width="20" height="4" rx="1" fill="url(#crownGoldLobby)" stroke="#5a3e15" strokeWidth="0.5"/>
            <defs>
              <linearGradient id="crownGoldLobby" x1="0" y1="0" x2="0" y2="1">
                <stop offset="0%" stopColor="#ffe58f"/>
                <stop offset="50%" stopColor="#d4af37"/>
                <stop offset="100%" stopColor="#8a6b20"/>
              </linearGradient>
            </defs>
          </svg>
        </div>

        {/* Layer 1: Outermost dark frame */}
        <div className="rounded-[22px] p-[3px]" style={{ background: 'linear-gradient(145deg, #2a1a0a, #0d0805, #2a1a0a)' }}>
          {/* Layer 2: Golden metallic rim */}
          <div className="rounded-[19px] p-[4px]" style={{ background: 'linear-gradient(160deg, #d4af37 0%, #a67c00 20%, #593d19 40%, #a67c00 60%, #d4af37 80%, #8a6b20 100%)' }}>
            {/* Layer 3: Inner dark edge */}
            <div className="rounded-[15px] p-[2px]" style={{ background: 'linear-gradient(145deg, #1a1008, #0a0604)' }}>
              {/* Layer 4: Inner golden trim */}
              <div className="rounded-[13px] p-[1px]" style={{ background: 'linear-gradient(160deg, #c89f59 0%, #5a4229 30%, #c89f59 60%, #5a4229 100%)' }}>
                {/* Layer 5: Main card body */}
                <div className="rounded-[12px] relative overflow-hidden" style={{ background: 'linear-gradient(180deg, #2c1a0e 0%, #1a0f08 30%, #140b06 70%, #0d0704 100%)' }}>
                  
                  {/* Leather texture simulation */}
                  <div className="absolute inset-0 pointer-events-none opacity-60" style={{
                    background: `
                      radial-gradient(ellipse at 30% 20%, rgba(139,90,43,0.25) 0%, transparent 50%),
                      radial-gradient(ellipse at 70% 80%, rgba(139,90,43,0.15) 0%, transparent 50%),
                      radial-gradient(ellipse at 50% 50%, rgba(90,55,20,0.3) 0%, transparent 70%)
                    `
                  }} />
                  <div className="absolute inset-0 pointer-events-none" style={{
                    boxShadow: 'inset 0 0 80px rgba(0,0,0,0.9), inset 0 0 30px rgba(0,0,0,0.5)'
                  }} />

                  {/* Decorative inner filigree border */}
                  <div className="absolute inset-[14px] pointer-events-none rounded-lg" style={{ border: '1px solid rgba(200,159,89,0.2)' }}>
                    {/* Corner scrollwork */}
                    <svg className="absolute -top-[6px] -left-[6px] w-5 h-5 text-[#c89f59] opacity-60" viewBox="0 0 20 20" fill="none" stroke="currentColor" strokeWidth="1.2">
                      <path d="M2 18 C2 10, 10 2, 18 2" /><path d="M6 18 C6 12, 12 6, 18 6" />
                    </svg>
                    <svg className="absolute -top-[6px] -right-[6px] w-5 h-5 text-[#c89f59] opacity-60" viewBox="0 0 20 20" fill="none" stroke="currentColor" strokeWidth="1.2">
                      <path d="M18 18 C18 10, 10 2, 2 2" /><path d="M14 18 C14 12, 8 6, 2 6" />
                    </svg>
                    <svg className="absolute -bottom-[6px] -left-[6px] w-5 h-5 text-[#c89f59] opacity-60" viewBox="0 0 20 20" fill="none" stroke="currentColor" strokeWidth="1.2">
                      <path d="M2 2 C2 10, 10 18, 18 18" /><path d="M6 2 C6 8, 12 14, 18 14" />
                    </svg>
                    <svg className="absolute -bottom-[6px] -right-[6px] w-5 h-5 text-[#c89f59] opacity-60" viewBox="0 0 20 20" fill="none" stroke="currentColor" strokeWidth="1.2">
                      <path d="M18 2 C18 10, 10 18, 2 18" /><path d="M14 2 C14 8, 8 14, 2 14" />
                    </svg>
                  </div>

                  {/* ════ CONTENT ════ */}
                  <div className="relative z-10 px-6 sm:px-10 pt-12 pb-6 flex flex-col items-center">
                    
                    {/* ROOM CODE */}
                    <SectionDivider text={t.lobby.roomCode} />
                    <div className="flex justify-center gap-1.5 sm:gap-2 mb-2 mt-2">
                      {roomCodeChars.map((char, i) => (
                        <div key={i} className="w-10 h-12 sm:w-12 sm:h-14 rounded-md flex items-center justify-center border" style={{
                          background: 'linear-gradient(180deg, rgba(15,10,6,0.95) 0%, rgba(20,12,7,0.9) 100%)',
                          borderColor: 'rgba(90,66,41,0.6)',
                          boxShadow: 'inset 0 4px 10px rgba(0,0,0,0.9), 0 2px 4px rgba(0,0,0,0.5)'
                        }}>
                          <span className="text-2xl sm:text-3xl font-serif font-black" style={{
                            background: 'linear-gradient(180deg, #ffe58f 0%, #d4af37 40%, #b8860b 100%)',
                            WebkitBackgroundClip: 'text',
                            WebkitTextFillColor: 'transparent',
                            filter: 'drop-shadow(0 2px 2px rgba(0,0,0,0.8))'
                          }}>
                            {char}
                          </span>
                        </div>
                      ))}
                    </div>
                    <div className="flex items-center justify-center gap-2 mb-8 w-full opacity-80">
                      <div className="w-6 h-[1px] bg-gradient-to-r from-transparent to-[#c89f59]/50" />
                      <button 
                        onClick={handleCopy}
                        className="flex items-center gap-1.5 px-2 py-1 rounded hover:bg-white/5 active:scale-95 transition-all"
                        title="Copy Room Code"
                      >
                        <p className="text-[10px] sm:text-xs text-[#c89f59] font-serif italic tracking-wide">
                          {copied ? t.lobby.copied : t.lobby.shareCode}
                        </p>
                        {!copied && (
                          <svg className="w-3 h-3 text-[#c89f59]" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                            <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M8 16H6a2 2 0 01-2-2V6a2 2 0 012-2h8a2 2 0 012 2v2m-6 12h8a2 2 0 002-2v-8a2 2 0 00-2-2h-8a2 2 0 00-2 2v8a2 2 0 002 2z" />
                          </svg>
                        )}
                      </button>
                      <div className="w-6 h-[1px] bg-gradient-to-l from-transparent to-[#c89f59]/50" />
                    </div>

                    {/* PLAYERS LIST */}
                    <SectionDivider text={`${t.lobby.players} (${playerCount}/${room.totalRounds > 0 ? 15 : 15})`} />
                    
                    <div className="w-full space-y-2 mt-2 mb-6 max-h-[35vh] overflow-y-auto pr-1 scrollbar-thin scrollbar-thumb-[#5a3e15] scrollbar-track-transparent">
                      {players.map((player) => {
                        // Resolve avatar: use avatarKey from server, fallback to local avatar for self
                        const resolvedAvatar = avatarKeyToUrl(player.avatarKey) || (player.id === myPlayerId ? myAvatar : null)
                        return (
                        <div key={player.id} className="relative rounded-lg p-[1px] shadow-md transition-all hover:brightness-110" style={{
                          background: 'linear-gradient(180deg, #b88c42, #5a3e15)'
                        }}>
                          <div className="flex items-center justify-between px-3 sm:px-4 py-2 sm:py-2.5 rounded-[7px] border border-[#0d0704]" style={{
                            background: 'linear-gradient(90deg, #1a0f08, #2c1a0e)'
                          }}>
                            <div className="flex items-center gap-3">
                              {/* Avatar Box */}
                              <div className="relative w-9 h-9 sm:w-10 sm:h-10 rounded-full border border-[#c89f59] bg-[#0d0704] flex items-center justify-center overflow-hidden shadow-[inset_0_2px_5px_rgba(0,0,0,0.8)]">
                                {resolvedAvatar ? (
                                  <img src={resolvedAvatar} alt="avatar" className="w-full h-full object-cover" />
                                ) : (
                                  <svg className="w-5 h-5 sm:w-6 sm:h-6 text-[#c89f59] opacity-70" viewBox="0 0 40 28" fill="currentColor">
                                    <path d="M20 2C14 2 10 8 10 12C10 16 14 20 16 20C18 20 18 18 20 16C22 18 22 20 24 20C26 20 30 16 30 12C30 8 26 2 20 2Z" />
                                    <circle cx="15" cy="11" r="2.5" fill="#0d0704" />
                                    <circle cx="25" cy="11" r="2.5" fill="#0d0704" />
                                  </svg>
                                )}
                              </div>
                              <span className={`w-2 h-2 rounded-full ${player.isConnected ? 'bg-[#5ce65c] shadow-[0_0_8px_rgba(92,230,92,0.6)]' : 'bg-[#e65c5c]'}`} />
                              <span className="font-serif font-bold text-[#ffe58f] text-sm sm:text-base tracking-wider drop-shadow-md">
                                {player.username}
                              </span>
                            </div>
                            
                            {player.isHost && (
                              <div className="flex items-center gap-1.5 border border-[#c89f59]/40 rounded-full px-2 sm:px-2.5 py-0.5" style={{ background: 'rgba(212,175,55,0.1)' }}>
                                <svg className="w-3 h-3 text-[#d4af37]" viewBox="0 0 48 36" fill="currentColor">
                                  <path d="M24 0L28 14L36 6L32 20H16L12 6L20 14L24 0Z" />
                                </svg>
                                <span className="text-[9px] sm:text-[10px] font-bold text-[#d4af37] tracking-widest uppercase">{t.lobby.host}</span>
                              </div>
                            )}
                          </div>
                        </div>
                      )})}
                    </div>

                    {/* WARNING / STATUS */}
                    <div className="w-full mb-4">
                      {playerCount < 3 ? (
                        <div className="w-full bg-[#2a0808]/80 border border-[#8a1c1c]/60 rounded-md py-2.5 flex justify-center items-center gap-2 shadow-inner">
                          <svg className="w-4 h-4 text-[#ff6b6b]" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2">
                            <circle cx="12" cy="12" r="10"/><line x1="12" y1="8" x2="12" y2="12"/><line x1="12" y1="16" x2="12.01" y2="16"/>
                          </svg>
                          <span className="text-[#ff8f8f] font-serif text-xs sm:text-sm drop-shadow-md">
                            {t.lobby.needPlayers} ({playerCount})
                          </span>
                        </div>
                      ) : !isHost ? (
                        <div className="w-full text-center py-2">
                          <span className="text-[#c89f59] font-serif text-xs sm:text-sm italic drop-shadow-md">
                            {t.lobby.waitingForHost}
                          </span>
                        </div>
                      ) : null}
                    </div>

                    {/* START BUTTON (HOST ONLY) */}
                    {isHost && (
                      <button
                        onClick={handleStartGame}
                        disabled={!canStart || loading}
                        className="w-full relative group rounded-lg active:scale-[0.98] transition-all disabled:opacity-50 disabled:cursor-not-allowed focus:outline-none"
                      >
                        <div className="absolute -inset-[1px] rounded-lg opacity-60 group-hover:opacity-80 transition-opacity" style={{
                          background: 'linear-gradient(180deg, #ffe58f, #a67c00)'
                        }} />
                        <div className="relative rounded-lg py-4 flex items-center justify-center gap-3" style={{
                          background: 'linear-gradient(180deg, #c9a033 0%, #9a7220 40%, #7a5a18 100%)',
                          boxShadow: 'inset 0 1px 1px rgba(255,229,143,0.5), inset 0 -2px 4px rgba(0,0,0,0.4), 0 6px 20px rgba(0,0,0,0.7)',
                        }}>
                          {/* Left Mask Icon */}
                          <svg className="w-5 h-5 text-[#ffe58f] drop-shadow-md opacity-80" viewBox="0 0 40 28" fill="currentColor">
                            <path d="M20 2C14 2 10 8 10 12C10 16 14 20 16 20C18 20 18 18 20 16C22 18 22 20 24 20C26 20 30 16 30 12C30 8 26 2 20 2Z" />
                            <circle cx="15" cy="11" r="2.5" fill="#5a3e15" /><circle cx="25" cy="11" r="2.5" fill="#5a3e15" />
                          </svg>
                          
                          <span className="font-serif font-black text-[15px] sm:text-[17px] tracking-[0.15em] uppercase whitespace-nowrap" style={{
                            background: 'linear-gradient(180deg, #fff8e1 0%, #ffe58f 50%, #d4af37 100%)',
                            WebkitBackgroundClip: 'text',
                            WebkitTextFillColor: 'transparent',
                            filter: 'drop-shadow(0 2px 3px rgba(0,0,0,0.7))',
                          }}>
                            {loading ? t.lobby.starting : `${t.lobby.startGame} (${playerCount})`}
                          </span>

                          {/* Right Mask Icon */}
                          <svg className="w-5 h-5 text-[#ffe58f] drop-shadow-md opacity-80" viewBox="0 0 40 28" fill="currentColor">
                            <path d="M20 2C14 2 10 8 10 12C10 16 14 20 16 20C18 20 18 18 20 16C22 18 22 20 24 20C26 20 30 16 30 12C30 8 26 2 20 2Z" />
                            <circle cx="15" cy="11" r="2.5" fill="#5a3e15" /><circle cx="25" cy="11" r="2.5" fill="#5a3e15" />
                          </svg>
                        </div>
                      </button>
                    )}

                    {error && (
                      <div className="w-full mt-3 text-center">
                        <span className="text-[#ff6b6b] font-serif text-sm font-bold">{error}</span>
                      </div>
                    )}

                  </div>
                </div>
              </div>
            </div>
          </div>
        </div>
      </div>
    </div>
  )
}

function SectionDivider({ text }: { text: string }) {
  return (
    <div className="flex items-center justify-center gap-3 w-full">
      <div className="flex-1 h-[1px]" style={{ background: 'linear-gradient(90deg, transparent, rgba(200,159,89,0.4))' }} />
      <span className="font-serif font-bold text-[11px] sm:text-[13px] uppercase tracking-[0.25em] text-[#c89f59] whitespace-nowrap drop-shadow-md">
        {text}
      </span>
      <div className="flex-1 h-[1px]" style={{ background: 'linear-gradient(90deg, rgba(200,159,89,0.4), transparent)' }} />
    </div>
  )
}

import { useEffect, useRef, useState } from 'react'
import { getAblyClient } from '../../lib/ably'
import { supabase } from '../../lib/supabase'
import { useGameStore } from '../../stores/gameStore'
import { useProfileStore } from '../../stores/profileStore'
import { useLanguageStore } from '../../stores/languageStore'


export default function WorldChat() {
  const {
    worldChatMessages,
    worldChatOnlineCount,
    setWorldChatMessages,
    addWorldChatMessage,
    setWorldChatOnlineCount,
    myPlayerId,
  } = useGameStore()
  const { name } = useProfileStore()
  const { t } = useLanguageStore()

  const [input, setInput] = useState('')
  const [loading, setLoading] = useState(true)
  const [sending, setSending] = useState(false)
  const [errorMsg, setErrorMsg] = useState('')
  const [reportingId, setReportingId] = useState<string | null>(null)

  const channelRef = useRef<any>(null)
  const messagesEndRef = useRef<HTMLDivElement>(null)
  const scrollContainerRef = useRef<HTMLDivElement>(null)
  const lastSentAt = useRef<number>(0)
  const isAutoScrollEnabled = useRef(true)

  // Determine username color based on hash for consistency
  const getUsernameColor = (id: string) => {
    let hash = 0
    for (let i = 0; i < id.length; i++) {
      hash = id.charCodeAt(i) + ((hash << 5) - hash)
    }
    const hue = Math.abs(hash % 360)
    return `hsl(${hue}, 70%, 65%)`
  }

  // Load initial history
  useEffect(() => {
    const loadHistory = async () => {
      setLoading(true)
      const { data, error } = await supabase
        .from('world_chat')
        .select('id, player_id, username, message, created_at')
        .order('created_at', { ascending: false })
        .limit(50)

      if (!error && data) {
        const history = data.reverse().map(d => ({
          id: d.id,
          playerId: d.player_id,
          username: d.username,
          message: d.message,
          timestamp: new Date(d.created_at).getTime()
        }))
        setWorldChatMessages(history)
      }
      setLoading(false)
    }

    // Only load if empty to prevent jumping
    if (useGameStore.getState().worldChatMessages.length === 0) {
      loadHistory()
    } else {
      setLoading(false)
    }
  }, [setWorldChatMessages])

  // Ably Pub/Sub & Presence
  useEffect(() => {
    if (!myPlayerId || !name) return

    const client = getAblyClient()
    const channel = client.channels.get('world-chat')
    channelRef.current = channel

    // Message subscription
    const onMessage = (msg: any) => {
      console.log('[Ably] Received message:', msg)
      if (msg.name === 'message' || msg.data?.message) {
        addWorldChatMessage(msg.data)
      }
    }
    // Subscribe to ALL events on the channel
    channel.subscribe(onMessage)

    // Presence update helper
    const updateCount = async () => {
      const members = await channel.presence.get()
      setWorldChatOnlineCount(members.length)
    }

    // Presence subscription
    channel.presence.subscribe('enter', updateCount)
    channel.presence.subscribe('leave', updateCount)

    // Enter presence
    channel.presence.enter({ username: name, playerId: myPlayerId }).then(updateCount)

    return () => {
      channel.presence.leave()
      channel.presence.unsubscribe('enter', updateCount)
      channel.presence.unsubscribe('leave', updateCount)
      channel.unsubscribe(onMessage)
      // Do not close client as it is a singleton
    }
  }, [myPlayerId, name, addWorldChatMessage, setWorldChatOnlineCount])

  // Auto-scroll logic
  const handleScroll = () => {
    if (!scrollContainerRef.current) return
    const { scrollTop, scrollHeight, clientHeight } = scrollContainerRef.current
    // If we are within 50px of the bottom, enable auto-scroll
    isAutoScrollEnabled.current = scrollHeight - scrollTop - clientHeight < 50
  }

  useEffect(() => {
    if (isAutoScrollEnabled.current) {
      messagesEndRef.current?.scrollIntoView({ behavior: 'smooth' })
    }
  }, [worldChatMessages])

  const handleSend = async (e?: React.FormEvent) => {
    e?.preventDefault()
    const trimmed = input.trim()
    if (!trimmed || !myPlayerId) return

    const now = Date.now()
    if (now - lastSentAt.current < 1500) {
      setErrorMsg('Slow down...')
      setTimeout(() => setErrorMsg(''), 1500)
      return
    }

    setSending(true)
    setInput('') // Optimistic clear
    lastSentAt.current = now

    // Optimistic Update: Instantly show message in UI
    addWorldChatMessage({
      id: `temp-${now}`,
      playerId: myPlayerId,
      username: name,
      message: trimmed,
      timestamp: now
    })

    try {
      const session = await supabase.auth.getSession()
      const token = session.data.session?.access_token
      if (!token) throw new Error('Not authenticated')

      const res = await supabase.functions.invoke('send-world-chat', {
        body: { message: trimmed },
        headers: { Authorization: `Bearer ${token}` }
      })

      if (res.error) {
        throw new Error(res.error.message || 'Failed to send')
      }
    } catch (err: any) {
      console.error(err)
      setErrorMsg(err.message || 'Error sending message')
      setInput(trimmed) // Restore input on failure

      // Rollback optimistic update
      const { worldChatMessages, setWorldChatMessages } = useGameStore.getState()
      setWorldChatMessages(worldChatMessages.filter(m => m.id !== `temp-${now}`))

      setTimeout(() => setErrorMsg(''), 3000)
    } finally {
      setSending(false)
    }
  }

  const handleKeyDown = (e: React.KeyboardEvent) => {
    if (e.key === 'Enter' && !e.shiftKey) {
      e.preventDefault()
      handleSend()
    }
  }

  const handleReport = async (messageId: string) => {
    if (reportingId) return
    setReportingId(messageId)
    try {
      const session = await supabase.auth.getSession()
      const token = session.data.session?.access_token
      if (!token) return

      await supabase.functions.invoke('report-world-chat', {
        body: { messageId },
        headers: { Authorization: `Bearer ${token}` }
      })
      alert(t.chat.reportSuccess)
    } catch (err) {
      console.error(err)
    } finally {
      setReportingId(null)
    }
  }

  return (
    <div className="flex flex-col h-full bg-[#110d0a] border border-[#5a3e15]/40 rounded-xl overflow-hidden shadow-2xl">
      {/* Header */}
      <div className="flex items-center justify-between px-4 py-3 bg-[#1a120e] border-b border-[#5a3e15]/40">
        <h2 className="text-sm font-black tracking-widest text-[#d4af37] uppercase font-serif flex items-center gap-2">
          <svg className="w-4 h-4" viewBox="0 0 24 24" fill="currentColor">
            <path d="M12 2C6.48 2 2 6.48 2 12s4.48 10 10 10 10-4.48 10-10S17.52 2 12 2zm-1 17.93c-3.95-.49-7-3.85-7-7.93 0-.62.08-1.21.21-1.79L9 15v1c0 1.1.9 2 2 2v1.93zm6.9-2.54c-.26-.81-1-1.39-1.9-1.39h-1v-3c0-.55-.45-1-1-1H8v-2h2c.55 0 1-.45 1-1V7h2c1.1 0 2-.9 2-2v-.41c2.93 1.19 5 4.06 5 7.41 0 2.08-.8 3.97-2.1 5.39z"/>
          </svg>
          {t.chat.worldChat}
        </h2>
        <div className="flex items-center gap-2 text-xs text-[#c89f59]/80 font-medium bg-[#0d0704] px-2 py-1 rounded border border-[#5a3e15]/30">
          <span className="w-2 h-2 rounded-full bg-emerald-500 shadow-[0_0_8px_rgba(16,185,129,0.6)] animate-pulse"></span>
          {worldChatOnlineCount} {t.chat.online}
        </div>
      </div>

      {/* Messages Area */}
      <div 
        ref={scrollContainerRef}
        onScroll={handleScroll}
        className="flex-1 overflow-y-auto p-4 space-y-4 scrollbar-thin scrollbar-thumb-[#5a3e15]/40 scrollbar-track-transparent"
        style={{ backgroundImage: 'radial-gradient(circle at center, rgba(90,55,20,0.05) 0%, transparent 100%)' }}
      >
        {loading ? (
          <div className="flex flex-col gap-4 animate-pulse opacity-50">
            {[1, 2, 3].map(i => (
              <div key={i} className={`flex gap-2 ${i % 2 === 0 ? 'flex-row-reverse' : ''}`}>
                <div className="w-8 h-8 rounded-full bg-[#5a3e15]/40"></div>
                <div className="w-32 h-10 rounded-lg bg-[#5a3e15]/20"></div>
              </div>
            ))}
          </div>
        ) : worldChatMessages.length === 0 ? (
          <div className="h-full flex flex-col items-center justify-center text-center opacity-40">
            <svg className="w-12 h-12 text-[#c89f59] mb-2" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.5">
              <path strokeLinecap="round" strokeLinejoin="round" d="M8 12h.01M12 12h.01M16 12h.01M21 12c0 4.418-4.03 8-9 8a9.863 9.863 0 01-4.255-.949L3 20l1.395-3.72C3.512 15.042 3 13.574 3 12c0-4.418 4.03-8 9-8s9 3.582 9 8z" />
            </svg>
            <p className="text-[#c89f59] font-medium text-sm">{t.chat.noMessages}<br/>{t.chat.beFirst}</p>
          </div>
        ) : (
          worldChatMessages.map((msg, idx) => {
            const isMe = msg.playerId === myPlayerId || msg.username === name
            const showHeader = idx === 0 || worldChatMessages[idx - 1].playerId !== msg.playerId || msg.timestamp - worldChatMessages[idx - 1].timestamp > 60000

            // Format relative time (e.g. "2m ago", "just now")
            const diffMs = Date.now() - msg.timestamp
            let timeStr = t.chat.justNow
            if (diffMs > 3600000) timeStr = `${Math.floor(diffMs / 3600000)}${t.chat.hours} ${t.chat.ago}`
            else if (diffMs > 60000) timeStr = `${Math.floor(diffMs / 60000)}${t.chat.minutes} ${t.chat.ago}`

            return (
              <div key={msg.id} className={`flex flex-col group ${isMe ? 'items-end' : 'items-start'}`}>
                {showHeader && (
                  <div className="flex items-baseline gap-2 mb-1 px-1">
                    {!isMe && <span className="text-[11px] font-bold" style={{ color: getUsernameColor(msg.playerId) }}>{msg.username}</span>}
                    {isMe && <span className="text-[11px] font-bold text-[#c89f59]">{t.chat.you}</span>}
                    <span className="text-[9px] text-white/30 font-medium">{timeStr}</span>
                  </div>
                )}
                <div className="flex items-center gap-2 group-hover:gap-3 transition-all">
                  {/* Left Report Button (for others' messages) */}
                  {!isMe && (
                    <button 
                      onClick={() => handleReport(msg.id)}
                      disabled={reportingId === msg.id}
                      className="opacity-0 group-hover:opacity-100 transition-opacity p-1 text-white/20 hover:text-red-400 focus:outline-none"
                      title={t.chat.reportMessage}
                    >
                      <svg className="w-3 h-3" viewBox="0 0 24 24" fill="currentColor">
                        <path d="M14.4 6L14 4H5v17h2v-7h5.6l.4 2h7V6z"/>
                      </svg>
                    </button>
                  )}

                  {/* Message Bubble */}
                  <div 
                    className={`max-w-[220px] sm:max-w-[260px] px-3 py-2 rounded-xl text-sm break-words whitespace-pre-wrap leading-relaxed shadow-sm
                      ${isMe 
                        ? 'bg-gradient-to-br from-[#d4af37]/20 to-[#8a6b20]/10 text-white/90 rounded-br-sm border border-[#d4af37]/20' 
                        : 'bg-[#1a120e] text-white/80 rounded-bl-sm border border-[#5a3e15]/40'
                      }`}
                  >
                    {msg.message}
                  </div>

                  {/* Right Report Button (shouldn't report own messages but space filler for alignment if needed, not necessary) */}
                </div>
              </div>
            )
          })
        )}
        <div ref={messagesEndRef} />
      </div>

      {/* Input Area */}
      <div className="p-3 bg-[#1a120e] border-t border-[#5a3e15]/40">
        <form onSubmit={handleSend} className="relative flex items-end gap-2">
          <div className="flex-1 relative">
            <textarea
              value={input}
              onChange={(e) => setInput(e.target.value.slice(0, 200))}
              onKeyDown={handleKeyDown}
              placeholder={t.chat.saySomething}
              disabled={sending}
              rows={input.split('\n').length > 1 ? Math.min(input.split('\n').length, 3) : 1}
              className="w-full bg-[#0a0604] border border-[#5a3e15]/50 rounded-lg px-3 py-2.5 text-sm text-white placeholder-white/30 focus:outline-none focus:border-[#d4af37]/50 focus:ring-1 focus:ring-[#d4af37]/30 transition-all resize-none overflow-hidden"
              style={{ minHeight: '42px' }}
            />
            {input.length > 0 && (
              <div className={`absolute right-2 bottom-2 text-[10px] ${input.length >= 200 ? 'text-red-400 font-bold' : 'text-white/30'}`}>
                {input.length}/200
              </div>
            )}
          </div>
          <button
            type="submit"
            disabled={!input.trim() || sending}
            className="flex-shrink-0 h-[42px] w-[42px] rounded-lg bg-gradient-to-b from-[#d4af37] to-[#aa8c2c] text-[#0a0604] flex items-center justify-center disabled:opacity-50 disabled:grayscale transition-all active:scale-95 shadow-lg"
          >
            {sending ? (
              <div className="w-4 h-4 border-2 border-[#0a0604]/20 border-t-[#0a0604] rounded-full animate-spin" />
            ) : (
              <svg className="w-5 h-5 ml-0.5" viewBox="0 0 24 24" fill="currentColor">
                <path d="M2.01 21L23 12 2.01 3 2 10l15 2-15 2z"/>
              </svg>
            )}
          </button>
        </form>
        {errorMsg && (
          <p className="absolute bottom-14 left-4 text-xs text-red-400 bg-red-950/80 px-2 py-1 rounded animate-fade-in border border-red-900/50 backdrop-blur-sm">
            {errorMsg}
          </p>
        )}
      </div>
    </div>
  )
}

import { useEffect, useState } from 'react'
import { useSearchParams, useNavigate } from 'react-router-dom'
import { useGameStore } from '../../stores/gameStore'
import { supabase } from '../../lib/supabase'
import { playClick } from '../../utils/sounds'
import { useLanguageStore } from '../../stores/languageStore'
import type { FinalScore } from '../../types/game'
import mainGameDesktopBg from '../../assets/main_game_desktop.webp'
import mobileBg from '../../assets/main_game.webp'
import { avatarKeyToUrl } from '../../utils/avatarMap'
import { Users, AlertCircle, RefreshCw, Home, BarChart2, X } from 'lucide-react'
import { useRoom } from '../../hooks/useRoom'
import { useProfileStore } from '../../stores/profileStore'

export default function ResultsPage() {
  const navigate = useNavigate()
  const [searchParams] = useSearchParams()
  const roomCode = searchParams.get('room')

  const finalScores = useGameStore((s) => s.finalScores)
  const setFinalScores = useGameStore((s) => s.setFinalScores)
  const players = useGameStore((s) => s.players) // Use players to get avatarKey
  const resetStore = useGameStore((s) => s.reset)
  const myPlayerId = useGameStore((s) => s.myPlayerId)
  const { t } = useLanguageStore()

  const { joinRoom } = useRoom()
  const { name } = useProfileStore()

  const [localScores, setLocalScores] = useState<FinalScore[]>([])
  const [loading, setLoading] = useState(false)
  const [resetting, setResetting] = useState(false)
  const [error, setError] = useState<string | null>(null)

  const [showScoreboard, setShowScoreboard] = useState(false)

  useEffect(() => {
    async function loadResults() {
      if (finalScores && finalScores.length > 0) {
        setLocalScores(finalScores)
        return
      }

      if (!roomCode) {
        setError('No room code provided.')
        return
      }

      setLoading(true)
      try {
        const { data: roomData, error: roomErr } = await supabase
          .from('rooms')
          .select('id')
          .eq('code', roomCode.toUpperCase())
          .maybeSingle()

        if (roomErr || !roomData) {
          setError('Room not found.')
          return
        }

        const { data: playersData, error: playersErr } = await supabase
          .from('room_players')
          .select('player_id, username, score, avatar_key')
          .eq('room_id', roomData.id)

        if (playersErr || !playersData) {
          setError('Failed to fetch player scores.')
          return
        }

        const sorted = [...playersData]
          .sort((a, b) => b.score - a.score)
          .map((p, idx) => {
            const storePlayer = players.find(sp => sp.id === p.player_id)
            return {
              playerId: p.player_id,
              username: p.username,
              totalScore: p.score,
              rank: idx + 1,
              avatarKey: storePlayer?.avatarKey || p.avatar_key || null,
            }
          })

        setLocalScores(sorted as any)
        setFinalScores(sorted as any)
      } catch (err) {
        setError(err instanceof Error ? err.message : 'Failed to load results.')
      } finally {
        setLoading(false)
      }
    }
    loadResults()
  }, [roomCode, finalScores, setFinalScores])

  function handleLobbyRedirect() {
    playClick()
    resetStore()
    navigate('/')
  }

  async function handlePlayAgain() {
    playClick()

    setResetting(true)
    setError(null)
    try {
      const { data: { session } } = await supabase.auth.getSession()
      if (!session || !roomCode) return

      const { data: roomData } = await supabase
        .from('rooms')
        .select('id, host_id')
        .eq('code', roomCode.toUpperCase())
        .maybeSingle()

      if (roomData) {
        // If host, attempt to reset the game first
        if (roomData.host_id === myPlayerId) {
          const response = await supabase.functions.invoke('reset-game', {
            body: { roomId: roomData.id },
            headers: { Authorization: `Bearer ${session.access_token}` },
          })
          if (response.error) {
             console.error("Reset failed:", response.error)
          }
        }

        // Wait a small bit for DB to propagate the phase change to WAITING
        await new Promise(r => setTimeout(r, 500))

        // Attempt to rejoin the room
        const joinedCode = await joinRoom(name.trim(), roomCode)
        if (joinedCode) {
          resetStore()
          navigate(`/room/${joinedCode}`)
          return
        } else {
           // joinRoom returns null on error. useRoom stores error, but we can set a local one
           setError(roomData.host_id === myPlayerId ? "Failed to restart game." : "Waiting for host to play again...")
        }
      }
    } catch (e) {
      console.error(e)
    } finally {
      setResetting(false)
    }
  }

  if (loading) {
    return (
      <div className="min-h-screen bg-[#0a0a0a] flex flex-col items-center justify-center p-6">
        <div className="animate-spin h-10 w-10 border-4 border-amber-400 border-t-transparent rounded-full mb-4" />
        <p className="text-[#c89f59] text-sm font-serif font-bold uppercase tracking-widest">{t.game.calculatingStandings}</p>
      </div>
    )
  }

  if (error) {
    return (
