            background: 'linear-gradient(180deg, #d4af37 0%, #b8860b 40%, #8a6b20 100%)',
            boxShadow: 'inset 0 2px 4px rgba(255,255,255,0.3), 0 5px 20px rgba(0,0,0,0.8)'
          }}>
