  if (isLastRound) {
    await admin.from("rooms").update({ phase: "FINAL_RESULTS" }).eq("id", roomId);
    const sorted = [...players].sort((a, b) => b.score - a.score);
    const finalScores = sorted.map((p, i) => ({ playerId: p.player_id, username: p.username, totalScore: p.score, rank: i + 1 }));
    await sendBroadcast(admin, roomId, "GAME_ENDED", { finalScores });
    return jsonSuccess({ success: true, isLastRound: true }, cors);
  }

  // Next round
  const nextRound = room.current_round + 1;
  const fillerCount = players.length - 2;
  const fullRoleList = [
    { name: "Police", points: 0 }, { name: "Thief", points: 0 },
    ...ROLE_POOL.slice(0, fillerCount).map((r) => ({ name: r.name, points: r.points })),
  ];
  const shuffled = fisherYatesShuffle(fullRoleList);

  let policePlayerId: string | null = null;
  for (let i = 0; i < players.length; i++) {
    const { error: insErr } = await admin.from("player_roles").insert({
      room_id: roomId, player_id: players[i].player_id,
      round_number: nextRound, role: shuffled[i].name, role_points: shuffled[i].points,
    });
    if (insErr) {
      await admin.from("player_roles").delete().eq("room_id", roomId).eq("round_number", nextRound);
      return jsonError(`Failed to assign role: ${insErr.message}`, cors, 500);
    }
    if (shuffled[i].name === "Police") policePlayerId = players[i].player_id;
  }
  if (!policePlayerId) return jsonError("Critical: no Police assigned", cors, 500);

  const phaseEndsAt = new Date(Date.now() + 60000).toISOString();
  await admin.from("rooms").update({ 
    current_round: nextRound, 
    phase: "DISCUSSION"
  }).eq("id", roomId);

  await sendBroadcast(admin, roomId, "ROUND_STARTED", { roundNumber: nextRound, policeId: policePlayerId, phase: "DISCUSSION", phaseEndsAt });

  return jsonSuccess({ success: true, isLastRound: false }, cors);
});

import { createClient } from "https://esm.sh/@supabase/supabase-js@2";
import { sendBroadcast } from "../_shared/broadcast.ts";

const ALLOWED_ORIGINS = ["http://localhost:5173", "http://localhost:4173"];

function getCorsHeaders(req: Request): Record<string, string> {
  const origin = req.headers.get("Origin") ?? "";
  const isAllowed = true;
  return { 
    "Access-Control-Allow-Origin": isAllowed ? (origin || "*") : "", 
    "Access-Control-Allow-Headers": "authorization, x-client-info, apikey, content-type", 
    "Access-Control-Allow-Methods": "POST, OPTIONS" 
  };
}

function jsonError(msg: string, cors: Record<string, string>, status = 400): Response {
  return new Response(JSON.stringify({ error: msg }), { status, headers: { ...cors, "Content-Type": "application/json" } });
}

function jsonSuccess(data: Record<string, unknown>, cors: Record<string, string>): Response {
  return new Response(JSON.stringify(data), { status: 200, headers: { ...cors, "Content-Type": "application/json" } });
}

Deno.serve(async (req) => {
  const cors = getCorsHeaders(req);
  if (req.method === "OPTIONS") return new Response("ok", { headers: cors });
  if (req.method !== "POST") return jsonError("Method not allowed", cors, 405);

  const authHeader = req.headers.get("Authorization");
  if (!authHeader) return jsonError("Missing Authorization header", cors, 401);

  const supabaseUrl = Deno.env.get("SUPABASE_URL")!;
  const serviceRoleKey = Deno.env.get("SUPABASE_SERVICE_ROLE_KEY")!;

  const anonClient = createClient(supabaseUrl, Deno.env.get("SUPABASE_ANON_KEY")!, { 
    global: { headers: { Authorization: authHeader } } 
  });

  const { data: { user }, error: authError } = await anonClient.auth.getUser();
  if (authError || !user) return jsonError("Invalid or expired token", cors, 401);

  const admin = createClient(supabaseUrl, serviceRoleKey, {
    auth: { autoRefreshToken: false, persistSession: false },
    global: { headers: { Authorization: `Bearer ${serviceRoleKey}` } },
  });

  let body: { roomId?: unknown };
  try { 
    body = await req.json(); 
  } catch { 
    return jsonError("Invalid JSON body", cors); 
  }

  const { roomId } = body;
  if (typeof roomId !== "string" || !roomId) return jsonError("roomId is required", cors);

  const { data: room, error: rErr } = await admin.from("rooms").select("host_id, phase").eq("id", roomId).maybeSingle();
  if (rErr || !room) return jsonError(rErr?.message ?? "Room not found", cors, rErr ? 500 : 404);

  // Allow host to reset. Also allow reset if the host is disconnected? 
  // For simplicity, we just enforce host check for reset unless it's abandoned.
  if (room.host_id !== user.id) {
    // If not host, maybe check if host is disconnected
    const { data: hostPlayer } = await admin.from("room_players").select("is_connected").eq("room_id", roomId).eq("player_id", room.host_id).maybeSingle();
    if (hostPlayer && hostPlayer.is_connected) {
      return jsonError("Only the host can restart the game", cors, 403);
    }
  }

  // 1. Delete player roles and round results
  await admin.from("player_roles").delete().eq("room_id", roomId);
  await admin.from("round_results").delete().eq("room_id", roomId);

  // 2. Reset player scores to 0
  await admin.from("room_players").update({ score: 0 }).eq("room_id", roomId);

  // 3. Reset room phase to WAITING and current_round to 1
  await admin.from("rooms").update({ 
    phase: "WAITING",
    current_round: 1
  }).eq("id", roomId);

  // 4. Broadcast reset so clients can update their local state
  await sendBroadcast(admin, roomId, "GAME_RESET", {});

  return jsonSuccess({ success: true }, cors);
});

import { serve } from "https://deno.land/std@0.177.0/http/server.ts"
import { createClient } from "https://esm.sh/@supabase/supabase-js@2.39.3"

const corsHeaders = {
  'Access-Control-Allow-Origin': '*',
  'Access-Control-Allow-Headers': 'authorization, x-client-info, apikey, content-type',
}

serve(async (req) => {
  if (req.method === 'OPTIONS') {
    return new Response('ok', { headers: corsHeaders })
  }

  try {
    const supabaseUrl = Deno.env.get('SUPABASE_URL') ?? ''
    const supabaseServiceKey = Deno.env.get('SUPABASE_SERVICE_ROLE_KEY') ?? ''
    const ablyApiKey = Deno.env.get('ABLY_API_KEY') ?? ''

    if (!ablyApiKey) {
      throw new Error('ABLY_API_KEY is not configured')
    }

    const supabase = createClient(supabaseUrl, supabaseServiceKey)

    // 1. Verify JWT
    const authHeader = req.headers.get('Authorization')
    if (!authHeader) {
      return new Response(JSON.stringify({ error: 'Missing Auth header' }), { status: 401, headers: corsHeaders })
    }

    const { data: { user }, error: userError } = await supabase.auth.getUser(authHeader.replace('Bearer ', ''))
    if (userError || !user) {
      return new Response(JSON.stringify({ error: 'Unauthorized' }), { status: 401, headers: corsHeaders })
    }

    const playerId = user.id

    // 2. Parse payload
    const { message } = await req.json()
    if (!message || typeof message !== 'string') {
      return new Response(JSON.stringify({ error: 'Invalid message' }), { status: 400, headers: corsHeaders })
    }

    // 3. Validate message format
    const trimmedMessage = message.trim()
    if (trimmedMessage.length === 0) {
      return new Response(JSON.stringify({ error: 'Empty message' }), { status: 400, headers: corsHeaders })
    }
    if (trimmedMessage.length > 200) {
      return new Response(JSON.stringify({ error: 'Message too long' }), { status: 400, headers: corsHeaders })
    }
    // Max 3 consecutive newlines
    if (/\n{4,}/.test(trimmedMessage)) {
      return new Response(JSON.stringify({ error: 'Too many newlines' }), { status: 400, headers: corsHeaders })
    }

    // 4. Check if blocked
    const { data: blockedData, error: blockedError } = await supabase
      .from('world_chat_blocked')
      .select('player_id')
      .eq('player_id', playerId)
      .single()

    if (blockedData) {
      return new Response(JSON.stringify({ error: 'You are blocked from world chat.' }), { status: 403, headers: corsHeaders })
    }

    // 5. Rate limit: Max 3 messages in the last 5 seconds
    const fiveSecondsAgo = new Date(Date.now() - 5000).toISOString()
    const { count, error: countError } = await supabase
      .from('world_chat')
      .select('*', { count: 'exact', head: true })
      .eq('player_id', playerId)
      .gte('created_at', fiveSecondsAgo)

    if (countError) throw countError

    if (count !== null && count >= 3) {
      return new Response(JSON.stringify({ error: 'Rate limit exceeded. Please slow down.' }), { status: 429, headers: corsHeaders })
    }

    // 6. Fetch username
    // Usernames are in room_players, but actually `useProfileStore` saves to auth.users metadata?
    // Wait, the game uses anonymous auth with `raw_user_meta_data.username`
    const username = user.user_metadata?.username ?? 'Anonymous'

    // 7. Insert to database
    const { data: insertedMsg, error: insertError } = await supabase
      .from('world_chat')
      .insert({
        player_id: playerId,
        username,
        message: trimmedMessage
      })
      .select()
      .single()

    if (insertError) throw insertError

    // 8. Publish to Ably
    const ablyResp = await fetch(`https://rest.ably.io/channels/world-chat/messages`, {
      method: 'POST',
      headers: {
        Authorization: `Basic ${btoa(ablyApiKey)}`,
        'Content-Type': 'application/json',
      },
      body: JSON.stringify({
        name: 'message',
        data: {
          id: insertedMsg.id,
          playerId: insertedMsg.player_id,
          username: insertedMsg.username,
          message: insertedMsg.message,
          timestamp: new Date(insertedMsg.created_at).getTime()
        }
      })
    })

    if (!ablyResp.ok) {
      console.error('Ably error:', await ablyResp.text())
      throw new Error('Failed to publish to Ably')
    }

    return new Response(JSON.stringify({ success: true, id: insertedMsg.id }), {
      headers: { ...corsHeaders, 'Content-Type': 'application/json' },
    })
  } catch (error) {
    console.error(error)
    return new Response(JSON.stringify({ error: 'Internal Server Error' }), {
      status: 500,
      headers: { ...corsHeaders, 'Content-Type': 'application/json' },
    })
  }
})

